class Node {
  constructor(key, cnt = 1) {
    this.key = key; // stored key = actual_value - offset
    this.cnt = cnt;
    this.pri = Math.random();
    this.left = null;
    this.right = null;
    this.sz = cnt;
  }
}
function sz(n){ return n ? n.sz : 0; }
function upd(n){ if(n) n.sz = n.cnt + sz(n.left) + sz(n.right); }
function rotateRight(p){ const q = p.left; p.left = q.right; q.right = p; upd(p); upd(q); return q; }
function rotateLeft(p){ const q = p.right; p.right = q.left; q.left = p; upd(p); upd(q); return q; }
// Insert, erase, kthSmallest would follow standard treap logic using stored keys (x - offset)
```

